function historyAction(after:Doodle,before:Doodle){if(after.layers?.length!==before.layers?.length)return '圖層變更';for(const l of after.layers??[]){const old=before.layers?.find(x=>x.id===l.id);if(!old||old.ops===l.ops)continue;const op=l.ops.at(-1);return op?.kind==='stroke'?(op.stroke.brush==='eraser'?'擦除':op.stroke.brush==='smudge'?'塗抹':'筆跡'):op?.kind==='adjust'?'影像調整':op?.kind==='gradient'?'漸層':op?.kind==='fill'?'填色':op?.kind==='image'?'影像編輯':'選取／刪除'}return '畫布／圖層設定'}
